<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> images/gallery/hero.png</span></span>
